// Forwards one file as raw bytes: a JPG/PNG to a Meta resumable-upload session (a template's sample image),
// or a member's photo/file from the bot to the private wa-media store.
// The Code node only checks the request; the bytes go out through the "Send bytes" HTTP Request node,
// because a Code node on this n8n cannot send a binary body.
const CONFIRM='__CONFIRM_TOKEN__';
const SUPA='__SUPABASE_URL__';
const ALLOW_STORAGE=false; // the test copy switches this on, to store posters in its own storage
/* the private store of the photos and files members send on WhatsApp (the bot sends them here): <club id>/<phone>/<message id>.<type> */
const WA_MEDIA=SUPA+'/storage/v1/object/wa-media/';
const MEDIA_TYPES={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif','application/pdf':'pdf','audio/ogg':'ogg','audio/mpeg':'mp3','audio/aac':'aac','audio/amr':'amr','audio/mp4':'m4a','video/mp4':'mp4','video/3gpp':'3gp','application/msword':'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document':'docx','application/vnd.ms-excel':'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'xlsx','application/vnd.ms-powerpoint':'ppt','application/vnd.openxmlformats-officedocument.presentationml.presentation':'pptx','text/plain':'txt','text/csv':'csv','audio/opus':'opus','audio/wav':'wav','video/quicktime':'mov','image/heic':'heic'};
const b=($input.first().json.body)||{};
const fail=(error)=>[{json:{ok:false,error}}];
if(b.confirm!==CONFIRM) return fail('Not authorized.');
const url=String(b.target_url||'');
/* no dot segments in any spelling ("..", "%2e", a backslash): once the address is normalised they would lead
   somewhere else on the same host (another Graph API call, or another part of the database) */
const dots=/\.\.|%2e|\\/i.test(url);
const toMeta=!dots&&/^https:\/\/graph\.facebook\.com\/v\d+\.\d+\/upload:\S+$/.test(url);
const toStorage=ALLOW_STORAGE&&!dots&&/^\S+$/.test(url)&&url.startsWith(SUPA+'/storage/v1/object/');
const toWaMedia=!dots&&url.startsWith(WA_MEDIA)&&/^[0-9a-f-]{36}\/[0-9]{8,15}\/[A-Za-z0-9_.-]{1,120}\.[a-z0-9]{1,5}$/.test(url.slice(WA_MEDIA.length));
if(!toMeta&&!toStorage&&!toWaMedia) return fail('This upload address is not allowed.');
const mime=String(b.mime||'').toLowerCase();
if(toWaMedia){ if(!MEDIA_TYPES[mime]) return fail('This file type cannot be stored.'); }
else if(!['image/jpeg','image/png'].includes(mime)) return fail('Only JPG or PNG images can be sent.');
const data=String(b.file_base64||'').replace(/\s+/g,'');
if(!data||!/^[A-Za-z0-9+/]+=*$/.test(data)) return fail('No file data provided.');
const size=Math.floor(data.length*3/4)-(data.endsWith('==')?2:data.endsWith('=')?1:0);
if(toWaMedia?size>10*1024*1024:size>5*1024*1024) return fail(toWaMedia?'The file must be under 10 MB.':'The image must be under 5 MB.');
/* the length is declared up front: Meta's upload session ignores a body sent without it */
const headers={'Content-Type':mime,'Content-Length':String(size)};
for(const [k,v] of Object.entries(b.headers||{})) if(['authorization','file_offset','apikey','x-upsert'].includes(String(k).toLowerCase())) headers[k]=String(v);
return [{json:{ok:true,target_url:url,headers,size},binary:{data:{data,mimeType:mime,fileName:'upload.'+(MEDIA_TYPES[mime]||(mime==='image/png'?'png':'jpg'))}}}];

// Turns the upload's HTTP response into {ok, status, body}. The item's headers (with the access key)
// are not passed on, and this workflow keeps no execution data.
const r=$input.first().json||{};
/* the request itself failed (timeout, connection reset, a header value refused): "Send bytes" continues with
   an error item instead of stopping the run, so the caller still gets a reason. Keys are scrubbed from it. */
if(r.error!==undefined&&r.statusCode===undefined){
  const raw=typeof r.error==='string'?r.error:((r.error&&(r.error.message||r.error.description))||'unknown error');
  const clean=String(raw).replace(/(OAuth|Bearer)\s+\S+/gi,'$1 …').replace(/EAA[A-Za-z0-9]{10,}/g,'…').replace(/eyJ[\w-]+\.[\w-]+\.[\w-]+/g,'…').slice(0,200);
  return [{json:{ok:false,status:0,error:'The upload could not reach the server: '+clean}}];
}
const st=Number(r.statusCode||0);
let body=(r.body!==undefined)?r.body:r.data; /* the HTTP Request node puts a text reply in 'data' */
if(typeof body==='string'){ try{ body=JSON.parse(body); }catch(e){} }
if(st>=200&&st<300) return [{json:{ok:true,status:st,body}}];
/* Meta's upload host puts its reason in debug_info; the Graph API in error; Supabase in message */
const msg=(body&&body.error&&(body.error.error_user_msg||body.error.message))||(body&&body.debug_info&&body.debug_info.message)||(body&&body.message)||('HTTP '+st);
return [{json:{ok:false,status:st,body,error:'The upload was refused: '+msg}}];
